import React, { useState, useEffect } from 'react';

export default function Profile() {
  const [profile, setProfile] = useState(null);

  useEffect(() => {
    // Fetch profile data
    console.log('Loading profile...');
  }, []);

  return (
    <div className="profile-page">
      <h1>User Profile</h1>
      {profile ? (
        <div>
          <p>Profile information here</p>
        </div>
      ) : (
        <p>Loading...</p>
      )}
    </div>
  );
}
